class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10 ** 9 + 7
        def dec(s):
            l = list(s)
            i = len(l) - 1
            while l[i] == '0':
                l[i] = '9'
                i -= 1
            l[i] = str(int(l[i]) - 1)
            return ''.join(l).lstrip('0') or '0'
        def f(s):
            from functools import lru_cache
            n = len(s)
            @lru_cache(None)
            def dp(i, tot, tight):
                if i == n:
                    return 1 if min_sum <= tot <= max_sum else 0
                hi = int(s[i]) if tight else 9
                r = 0
                for d in range(hi + 1):
                    if tot + d > max_sum:
                        break
                    r = (r + dp(i + 1, tot + d, tight and d == hi)) % MOD
                return r
            return dp(0, 0, True)
        return (f(num2) - f(dec(num1))) % MOD

