class Solution {
public:
    const long long MOD = 1e9 + 7;
    int mn, mx;
    string s;
    long long memo[25][405][2];
    long long dp(int i, int tot, int tight) {
        if (i == (int)s.size()) return (tot >= mn && tot <= mx) ? 1 : 0;
        long long &r = memo[i][tot][tight];
        if (r != -1) return r;
        r = 0;
        int hi = tight ? s[i] - '0' : 9;
        for (int d = 0; d <= hi && tot + d <= mx; d++)
            r = (r + dp(i + 1, tot + d, tight && d == hi)) % MOD;
        return r;
    }
    long long f(const string& t) {
        s = t;
        memset(memo, -1, sizeof(memo));
        return dp(0, 0, 1);
    }
    string dec(string l) {
        int i = l.size() - 1;
        while (l[i] == '0') { l[i] = '9'; i--; }
        l[i]--;
        int z = 0; while (z + 1 < (int)l.size() && l[z] == '0') z++;
        return l.substr(z);
    }
    int count(string num1, string num2, int min_sum, int max_sum) {
        mn = min_sum; mx = max_sum;
        return ((f(num2) - f(dec(num1)) % MOD) % MOD + MOD) % MOD;
    }
};

