            for ch in t:
                d = int(ch)
                nf = [0] * (max_sum + 1); nt = [0] * (max_sum + 1)
                for s in range(max_sum + 1):
                    if free[s]:
                        for x in range(10):
                            if s + x <= max_sum: nf[s + x] = (nf[s + x] + free[s]) % MOD
