                                if x == d: nt[s + x] = (nt[s + x] + tight[s]) % MOD
                                else: nf[s + x] = (nf[s + x] + tight[s]) % MOD
                free, tight = nf, nt
            return (sum(free[min_sum:]) + sum(tight[min_sum:])) % MOD
